{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-ahamEJ/src/election.js","content":"/**
 * Runs an instant-runoff count and returns the list of rounds counted.
 * Each round is `{ votes, exhausted, eliminated, winner }`, where `votes` is
 * a `Map` from candidate name to that round's vote count for every
 * candidate still continuing at the start of the round, `eliminated` is the
 * name eliminated after the round (or `null` for the last round), and
 * `winner` is the winning name (or `null` if the round ended the election
 * with no winner).
 */
export function countRounds({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)
    const activeTotal = ballots.reduce((sum, b) => sum + b.count, 0) - exhausted

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null, winner: null })
      break
    }

    const winner = [...continuing].find((name) => votes.get(name) * 2 > activeTotal)
    if (winner !== undefined) {
      rounds.push({ votes, exhausted, eliminated: null, winner })
      break
    }

    const eliminated = pickElimination(continuing, votes, history)
    rounds.push({ votes, exhausted, eliminated, winner: null })
    continuing = new Set(continuing)
    continuing.delete(eliminated)
  }

  return rounds
}

/** Picks the candidate to eliminate this round, applying the tie-break rule. */
function pickElimination(continuing, votes, history) {
  const minVotes = Math.min(...[...continuing].map((name) => votes.get(name)))
  let tied = [...continuing].filter((name) => votes.get(name) === minVotes)

  while (tied.length > 1) {
    let narrowed = false
    for (const roundVotes of history) {
      const counts = tied.map((name) => roundVotes.get(name))
      if (counts.every((v) => v === counts[0])) continue
      const min = Math.min(...counts)
      tied = tied.filter((name) => roundVotes.get(name) === min)
      narrowed = true
      break
    }
    if (!narrowed) break
  }

  if (tied.length > 1) {
    tied = [tied.reduce((last, name) => (name > last ? name : last))]
  }

  return tied[0]
}
"}

