      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    history.push(votes)
    const activeTotal = ballots.reduce((sum, b) => sum + b.count, 0) - exhausted

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null, winner: null })
      break
