    if (winner !== undefined) {
      rounds.push({ votes, exhausted, eliminated: null, winner })
      break
    }

    const eliminated = pickElimination(continuing, votes, history)
    rounds.push({ votes, exhausted, eliminated, winner: null })
    continuing = new Set(continuing)
    continuing.delete(eliminated)
  }

  return rounds
}

/** Picks the candidate to eliminate this round, applying the tie-break rule. */
function pickElimination(continuing, votes, history) {
  const minVotes = Math.min(...[...continuing].map((name) => votes.get(name)))
